:root{
  --bg:#0B0E14; --panel:#12161F; --panel2:#171C28; --line:#1E2530;
  --text:#E6E9EF; --muted:#8B94A3; --green:#34D399; --red:#F87171;
  --amber:#F5B544; --blue:#60A5FA;
  --mono:ui-monospace,"SF Mono","Cascadia Mono",Menlo,Consolas,monospace;
  --sans:system-ui,-apple-system,"Segoe UI",Roboto,sans-serif;
}
*{box-sizing:border-box}
body{margin:0;background:var(--bg);color:var(--text);font-family:var(--sans);font-size:14px;line-height:1.45}
a{color:var(--blue);text-decoration:none}
a:hover{text-decoration:underline}
.hidden{display:none}
.muted{color:var(--muted)}
.num{font-family:var(--mono);text-align:right;white-space:nowrap}
.top{padding:14px 28px 0;border-bottom:1px solid var(--line)}
.title-row{display:flex;align-items:baseline;gap:12px}
h1{margin:0;font-size:26px;letter-spacing:2px;font-family:var(--mono)}
.model-tag{font-family:var(--mono);font-size:12px;color:var(--amber);border:1px solid var(--amber);border-radius:3px;padding:2px 7px}
.asof{font-family:var(--mono);font-size:12px;color:var(--muted)}
.subtitle{margin:4px 0 10px;color:var(--muted);max-width:1100px}
.strip{display:flex;flex-wrap:wrap;gap:8px 18px;font-family:var(--mono);font-size:12.5px;padding:8px 12px;border:1px solid var(--line);border-radius:6px;background:var(--panel);margin-bottom:8px}
.strip b{color:var(--green)}
.strip-validation b{color:var(--blue)}
.strip .warn{color:var(--amber)}
.tabs{display:flex;gap:4px;margin:10px 0 0}
.tabs a{padding:8px 16px;color:var(--muted);border:1px solid transparent;border-bottom:none;border-radius:6px 6px 0 0;font-weight:600}
.tabs a.active{color:var(--text);background:var(--panel);border-color:var(--line)}
main{padding:20px 28px 8px}
.kpi{display:grid;grid-template-columns:repeat(5,1fr);gap:12px;margin-bottom:16px}
.kpi .card{background:var(--panel);border:1px solid var(--line);border-radius:8px;padding:12px 14px}
.kpi .label{font-size:11px;letter-spacing:1px;text-transform:uppercase;color:var(--muted)}
.kpi .value{font-family:var(--mono);font-size:22px;font-weight:700;margin-top:4px}
.kpi .sub{font-size:12px;color:var(--muted)}
.filters{display:flex;flex-wrap:wrap;gap:10px;align-items:center;background:var(--panel);border:1px solid var(--line);border-radius:8px;padding:10px 12px;margin-bottom:18px}
.filters label{font-size:12px;color:var(--muted);display:flex;gap:6px;align-items:center}
select,input[type=text]{background:var(--panel2);color:var(--text);border:1px solid var(--line);border-radius:5px;padding:6px 8px;font-size:13px;font-family:var(--sans)}
.count{margin-left:auto;font-family:var(--mono);font-size:12px;color:var(--muted)}
.section-title{font-size:17px;margin:20px 0 10px}
.top5{display:grid;grid-template-columns:repeat(5,1fr);gap:12px}
.top5 .card{background:var(--panel);border:1px solid var(--line);border-radius:8px;padding:14px;cursor:pointer}
.top5 .card:hover{border-color:var(--amber)}
.top5 .rank{font-family:var(--mono);font-size:12px;color:var(--amber)}
.top5 .name{font-size:17px;font-weight:700;margin:4px 0 2px}
.top5 .cat{font-size:12px;color:var(--muted)}
.top5 .big{font-family:var(--mono);font-size:21px;font-weight:700;color:var(--amber);margin-top:8px}
.top5 .range{font-family:var(--mono);font-size:11.5px;color:var(--muted)}
.top5 .why{font-size:12.5px;color:var(--text);margin-top:8px;line-height:1.4}
.top5 .farm{font-family:var(--mono);font-size:12px;color:var(--green);margin-top:8px}
.bar{height:6px;background:var(--panel2);border-radius:3px;margin-top:6px;overflow:hidden}
.bar>i{display:block;height:100%;background:var(--amber)}
.bar.blue>i{background:var(--blue)}
table.board{width:100%;border-collapse:collapse;background:var(--panel);border:1px solid var(--line);border-radius:8px;overflow:hidden}
.board th,.board td{padding:8px 10px;border-bottom:1px solid var(--line);text-align:left;vertical-align:top}
.board thead th{font-size:11px;letter-spacing:1px;text-transform:uppercase;color:var(--muted);background:var(--panel2)}
.board tbody tr:hover{background:var(--panel2)}
.board tbody tr{cursor:pointer}
.board .nm{font-weight:700}
.board .why-cell{font-size:12.5px;color:var(--muted);max-width:340px}
.up{color:var(--green)} .down{color:var(--red)}
.odds{color:var(--blue)} .val{color:var(--amber);font-weight:700}
.foot-note{color:var(--muted);font-size:12.5px;margin:12px 0}
.back{font-size:13px}
.detail-head{display:flex;gap:16px;align-items:baseline;flex-wrap:wrap}
.detail-head h2{margin:0;font-size:24px}
.detail-grid{display:grid;grid-template-columns:1.15fr 1fr;gap:16px;margin-top:14px}
.panel{background:var(--panel);border:1px solid var(--line);border-radius:8px;padding:13px 16px}
.panel h3{margin:0 0 10px;font-size:14px;letter-spacing:1px;text-transform:uppercase;color:var(--muted)}
.term{display:grid;grid-template-columns:150px 90px 1fr 90px;gap:10px;align-items:center;padding:5px 0;border-bottom:1px solid var(--line);font-size:13px}
.term:last-child{border-bottom:none}
.term .t-name{color:var(--muted)}
.term .t-val{font-family:var(--mono);text-align:right}
.term .t-bar{height:8px;background:var(--panel2);border-radius:4px;overflow:hidden}
.term .t-bar>i{display:block;height:100%;background:var(--blue)}
.term .t-share{font-family:var(--mono);text-align:right;color:var(--amber)}
.range-line{font-family:var(--mono);font-size:15px;margin:6px 0 2px}
.range-line b{color:var(--amber)}
.steps{list-style:none;margin:0;padding:0}
.steps li{padding:4px 0;border-bottom:1px solid var(--line);font-size:13px;line-height:1.3}
.steps li:last-child{border-bottom:none}
.steps .cost{color:var(--green);font-family:var(--mono);font-size:12.5px}
.steps .step-n{font-family:var(--mono);color:var(--amber);margin-right:6px}
.risk{color:var(--red)}
.mind{color:var(--text)}
.method-body p{max-width:860px}
.method-body code{font-family:var(--mono);background:var(--panel2);padding:2px 5px;border-radius:4px;font-size:12.5px}
.method-body table{border-collapse:collapse;margin:10px 0}
.method-body td,.method-body th{border:1px solid var(--line);padding:6px 10px;font-size:13px;text-align:left}
.method-body th{color:var(--muted);font-weight:600}
.foot{padding:14px 28px 22px;color:var(--muted);font-size:12.5px;border-top:1px solid var(--line)}
@media (max-width:1100px){.top5{grid-template-columns:repeat(2,1fr)}.kpi{grid-template-columns:repeat(2,1fr)}.detail-grid{grid-template-columns:1fr}}
```

